function devHead(o){return'<thead><tr><th class="ck"><input type="checkbox" data-all></th><th>'+T("设备名","Device Name")+'</th>'+(o&&o.store?'<th>'+T("商家 › 门店","Merchant › store")+'</th>':'')+'<th>'+T("类型","Type")+'</th><th>ID</th><th>'+T("状态","Status")+'</th><th>'+T("同步","Sync")+'</th><th class="act"></th></tr></thead>'}
