 m.innerHTML='<div data-x="rn">✎ '+T("改名","Rename")+'</div><div data-x="mv">⇄ '+T("移动到…","Move to…")+'</div>'+(D.me.admin?'<div data-x="pw">🔒 '+T("单独密码（高级）","Custom password (advanced)")+'</div><div data-x="del" class="danger">'+T("删除设备","Delete device")+'</div>':'');
